    def process_order(self, order, engine, entrust_callback_func, need_max_entrade_get=True, strategyfare_id=''):
        iqd_code = order.symbol
        option_code, market = iqd_code.split('.')
        option_exch_type = OPT_EXCHANGE_TYPES_DICT.get(market, None)
        if option_exch_type is None:
            return ({'error_no': -1, 'error_info': '不支持的代码类型【%s】' % iqd_code}, None)
        elif order.entrust_direction == EntrustDirection.BUY:
            entrust_bs = '1'
        elif order.entrust_direction == EntrustDirection.SELL:
            entrust_bs = '2'
        else:
            return ({'error_no': -1, 'error_info': '不支持的委托方向类型：%s' % order.entrust_direction}, None)
        if order.futures_direction == FuturesDirection.OPEN:
            entrust_oc = 'O'
        elif order.futures_direction in (FuturesDirection.CLOSE, FuturesDirection.CLOSE_TODAY):
            entrust_oc = 'C'
        elif order.futures_direction == OptionDirection.EXECRISE:
            entrust_oc = 'X'
        else:
            return ({'error_no': -1, 'error_info': '不支持的开平仓类型：%s' % order.futures_direction}, None)
        if order.price:
            entrust_price = round(float(order.price), 4)
        else:
            snp = engine.data_proxy.get_snapshot(iqd_code)
            if not (snp and snp[iqd_code]):
                return ({'error_no': -1, 'error_info': '代码【%s】实时行情获取失败' % iqd_code}, None)
            else:
                entrust_price = snp[iqd_code].get('last_px', 0)
                if entrust_price == 0:
                    return ({'error_no': -1, 'error_info': '代码【%s】实时行情获取失败' % iqd_code}, None)
        covered_flag = ''
        if order.hedge_type is HedgeType.COVERED:
            covered_flag = '1'
        if order.futures_direction == OptionDirection.EXECRISE:
            entrust_prop = 'OTE'
        else:
            entrust_prop = '0'
        entrust_price = round(float(entrust_price), 4)
        amount = int(order.amount)
        kwargs = dict()
        kwargs['option_code'] = option_code
        kwargs['exchange_type'] = option_exch_type
        kwargs['opt_entrust_price'] = entrust_price
        kwargs['entrust_prop'] = entrust_prop
        kwargs['entrust_bs'] = entrust_bs
        kwargs['entrust_oc'] = entrust_oc
        kwargs['covered_flag'] = covered_flag
        kwargs['entrust_amount'] = amount
        kwargs['order'] = order
        kwargs['is_async'] = True
        kwargs['func'] = entrust_callback_func
        kwargs['entrust_reference'] = str(order.entrust_reference)
        system_log.debug(f"委托处理结束，发送订单，order_id：{order.order_id!s}，代码：{order.symbol!s}，当前时间：{datetime.datetime.now().strftime('%Y-%m-%d %H:%M:%S.%f')!s}")
        return self.trade_account.security_entrust(**(kwargs))
    def option_cancel_order(self, order, cancel_callback_func):
        exchange_type = ''
        option_code = order.symbol
        if option_code.endswith('XSHO'):
            exchange_type = '1'
        elif option_code.endswith('XSZO'):
            exchange_type = '2'
        entrust_no = order.entrust_no
        kwargs = dict()
        kwargs['is_async'] = True
        kwargs['func'] = cancel_callback_func
        kwargs['order'] = order
        entrust_date = datetime.datetime.now().strftime('%Y%m%d')
        error_dict, response = self.trade_account.func_option_entrust_withdraw(exchange_type=exchange_type, entrust_no=entrust_no, business_type='option', asset_prop='B', **(kwargs))
        return (error_dict, response)
    def entrust_rsp(self, event, order, is_cancel=False):
        entrust_rsp_handle(self.engine, order, event, is_cancel=is_cancel)
    def business_rsp(self, event, order, is_cancel=False):
        business_rsp_handle(self.engine, event, order, is_cancel=is_cancel)
